// translation.bar.reviewed 的 {lang} 佔位：zh 版用語言名稱
STRINGS['zh-TW']['translation.bar.reviewed'] = STRINGS['zh-TW']['translation.bar.reviewed'].replace('{lang}', '翻譯');

export function t(lang, key, vars = {}) {
  const s = STRINGS[lang]?.[key] ?? STRINGS.en?.[key] ?? STRINGS['zh-TW'][key] ?? key;
  return s.replace(/\{(\w+)\}/g, (_, k) => vars[k] ?? '');
}

if (typeof window !== 'undefined') { window.CDC = window.CDC || {}; window.CDC.t = (k, v) => t(document.documentElement.lang, k, v); window.CDC.STRINGS = STRINGS; }
